#!/usr/bin/env python3
"""regression-jest.py — generate a Jest regression test from a regression artifact.

Usage:
    python3 regression-jest.py <artifact-path> [--out tests/regression/]

TypeScript/Jest counterpart of regression-pytest.py. Same artifact format,
same Input/Expected output extraction, same hand-edit detection via content
hash. Emits a .test.ts file under tests/regression/.

Logging: this script is invoked by /qa, which logs qa_tests_generated. The
script itself doesn't log.
"""

import argparse
import hashlib
import json
import re
import sys
from datetime import datetime, timezone
from pathlib import Path


def parse_frontmatter(text: str) -> tuple[dict, str]:
    if not text.startswith("---\n"):
        return {}, text
    end = text.find("\n---\n", 4)
    if end < 0:
        return {}, text
    fm_text = text[4:end]
    body = text[end + 5:]
    fm = {}
    for line in fm_text.split("\n"):
        if ":" in line and not line.lstrip().startswith("#"):
            k, v = line.split(":", 1)
            fm[k.strip()] = v.strip()
    return fm, body


def extract_section(body: str, heading: str) -> str:
    pattern = re.compile(
        r"^##\s+" + re.escape(heading) + r"\s*\n(.*?)(?=^##\s|\Z)",
        re.MULTILINE | re.DOTALL,
    )
    m = pattern.search(body)
    return m.group(1).strip() if m else ""


def extract_code_block(section: str) -> tuple[str, str]:
    m = re.search(r"```(\w*)\s*\n(.*?)```", section, re.DOTALL)
    if not m:
        return "", ""
    return m.group(1), m.group(2).rstrip()


def slugify(s: str) -> str:
    s = re.sub(r"[^a-zA-Z0-9]+", "_", s)
    s = re.sub(r"_+", "_", s).strip("_").lower()
    return s or "regression"


def content_hash(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


def js_string_literal(s: str) -> str:
    """Encode a string for safe embedding in a JS template literal."""
    # Escape backticks, dollar braces, and backslashes
    s = s.replace("\\", "\\\\").replace("`", "\\`").replace("${", "\\${")
    return s


def generate(artifact_path: Path, out_dir: Path) -> Path:
    text = artifact_path.read_text(encoding="utf-8")
    fm, body = parse_frontmatter(text)

    if fm.get("language") not in ("typescript", "javascript", None, ""):
        raise SystemExit(
            f"regression-jest.py only handles typescript/javascript artifacts; "
            f"this artifact's language is '{fm.get('language')}'"
        )

    why = extract_section(body, "Why this regression exists")
    input_section = extract_section(body, "Input")
    output_section = extract_section(body, "Expected output")
    verification = extract_section(body, "Verification command")

    if not input_section:
        raise SystemExit(f"Artifact {artifact_path} has no '## Input' section")
    if not output_section:
        raise SystemExit(f"Artifact {artifact_path} has no '## Expected output' section")

    input_lang, input_code = extract_code_block(input_section)
    output_lang, output_code = extract_code_block(output_section)

    # JSON detection
    input_is_json = False
    output_is_json = False
    if input_lang in ("json", ""):
        try:
            json.loads(input_code)
            input_is_json = True
        except (json.JSONDecodeError, ValueError):
            pass
    if output_lang in ("json", ""):
        try:
            json.loads(output_code)
            output_is_json = True
        except (json.JSONDecodeError, ValueError):
            pass

    stem = artifact_path.stem
    test_desc_name = slugify(stem)
    chash = content_hash(text)

    parts = []
    parts.append(f"""// AUTO-GENERATED by specship /qa. Do not edit by hand.
// §qa:{artifact_path.as_posix()}
// To change this test, edit the source artifact and re-run /qa.
// Content hash: {chash}
// Generated at: {datetime.now(timezone.utc).isoformat(timespec='seconds')}

/**
 * Regression test for: {fm.get('regression_id', '<unknown>')}
 *
 * Parent fix: {fm.get('parent_fix', '<unknown>')}
 * Authored by: {fm.get('authored_by', '<unknown>')}
 * Authored at: {fm.get('authored_at', '<unknown>')}
 *
 * Why this regression exists:
{js_doc_indent(why or '(see source artifact)')}
 */

""")

    # Fixtures
    parts.append("// ---- Fixtures (extracted from the artifact's Input/Expected output) ----\n\n")
    if input_is_json:
        parts.append(f"const REGRESSION_INPUT = {input_code};\n\n")
    else:
        parts.append(f"const REGRESSION_INPUT = `{js_string_literal(input_code)}`;\n\n")

    if output_is_json:
        parts.append(f"const EXPECTED_OUTPUT = {output_code};\n\n")
    else:
        parts.append(f"const EXPECTED_OUTPUT = `{js_string_literal(output_code)}`;\n\n")

    # Test body
    parts.append(f"""describe('regression: {test_desc_name}', () => {{
  test.skip('verifies the regression fixed by {fm.get('parent_fix', '<unknown fix>')}', async () => {{
    // =========================================================================
    // CALL SITE — replace this block with the actual invocation.
    // Remove the .skip() above once wired up.
    // =========================================================================
    // Example for an HTTP API:
    //   import {{ request }} from 'supertest';
    //   import app from '../../src/app';
    //   const response = await request(app).post('/subscribe').send(REGRESSION_INPUT);
    //   const actual = response.body;
    //
    // Example for a function:
    //   import {{ theFunction }} from '../../src/module';
    //   const actual = theFunction(REGRESSION_INPUT);
    //
    const actual: unknown = null;  // <-- REPLACE THIS
    // =========================================================================

""")

    if output_is_json:
        parts.append("""    // The expected output was parsed as JSON. Asserts structural equality.
    expect(actual).toEqual(EXPECTED_OUTPUT);
""")
    else:
        parts.append("""    // The expected output is a raw string. Adapt the comparison to your
    // response type (string equality, regex match, etc.).
    expect(String(actual).trim()).toBe(EXPECTED_OUTPUT.trim());
""")

    parts.append("  });\n})\n;\n")

    # Verification breadcrumb
    if verification:
        v_lang, v_cmd = extract_code_block(verification)
        if v_cmd:
            parts.append("\n// Verification command (from artifact):\n")
            for line in v_cmd.split("\n"):
                parts.append(f"//   {line}\n")

    content = "".join(parts)

    out_dir.mkdir(parents=True, exist_ok=True)
    test_file = out_dir / f"{slugify(stem)}.test.ts"
    test_file.write_text(content, encoding="utf-8")
    return test_file


def js_doc_indent(text: str) -> str:
    return "\n".join(" * " + line for line in text.split("\n"))


def main() -> int:
    p = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    p.add_argument("artifact", help="path to the regression artifact")
    p.add_argument("--out", default="tests/regression", help="output directory")
    args = p.parse_args()

    artifact_path = Path(args.artifact)
    if not artifact_path.is_file():
        print(f"artifact not found: {artifact_path}", file=sys.stderr)
        return 1

    try:
        test_file = generate(artifact_path, Path(args.out))
    except SystemExit as e:
        print(str(e), file=sys.stderr)
        return 1

    print(str(test_file))
    return 0


if __name__ == "__main__":
    sys.exit(main())
